    return "---\nid: sdd-tools-implementation-list-changed-files-source\nfill_sections: [overview, source, changes]\ncapability_refs:\n  - id: td-cb-lifecycle-automation\n    role: primary\n    gap: td-lifecycle-dispatch\n    claim: td-lifecycle-dispatch\n    coverage: full\n    rationale: \"Tool TDs implement TD/CB lifecycle artifact authoring, review, revision, merge, and validation commands.\"\n---\n\n# List Changed Files Tool\n\n## Overview\n<!-- type: overview lang: markdown -->\n\nPublic API manifest for `apps/agentic-workflow/src/tools/implementation.rs` generated from AST during Score force-regeneration standardization.\n\n### Symbols\n\n| Name | Target | Kind | Visibility | Line | Signature |\n|------|--------|------|------------|------|-----------|\n| `create_merge_review_definition` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 687 | create_merge_review_definition() -> ToolDefinition |\n| `create_review_definition` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 477 | create_review_definition() -> ToolDefinition |\n| `execute_create_merge_review` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 781 | execute_create_merge_review(args: &Value, project_root: &Path) -> Result<String> |\n| `execute_create_review` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 559 | execute_create_review(args: &Value, project_root: &Path) -> Result<String> |\n| `execute_list_changed_files` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 356 | execute_list_changed_files(args: &Value, _project_root: &Path) -> Result<String> |\n| `execute_read_all_requirements` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 117 | execute_read_all_requirements(args: &Value, project_root: &Path) -> Result<String> |\n| `execute_read_implementation_summary` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 232 | execute_read_implementation_summary(args: &Value, _project_root: &Path) -> Result<String> |\n| `list_changed_files_definition` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 323 | list_changed_files_definition() -> ToolDefinition |\n| `read_all_requirements_definition` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 93 | read_all_requirements_definition() -> ToolDefinition |\n| `read_implementation_summary_definition` | apps/agentic-workflow/src/tools/implementation.rs | function | pub | 204 | read_implementation_summary_definition() -> ToolDefinition |\n## Source\n<!-- type: source lang: rust -->\n\n````rust\n/// Get the tool definition for list_changed_files\npub fn list_changed_files_definition() -> ToolDefinition {\n    ToolDefinition {\n        name: \"sdd_list_changed_files\".to_string(),\n        description: \"List changed files with detailed statistics (additions/deletions)\"\n            .to_string(),\n        input_schema: json!({\n            \"type\": \"object\",\n            \"required\": [\"project_path\", \"change_id\"],\n            \"properties\": {\n                \"project_path\": {\n                    \"type\": \"string\",\n                    \"description\": \"Project root path (use $PWD for current directory)\"\n                },\n                \"change_id\": {\n                    \"type\": \"string\",\n                    \"description\": \"The change ID to list files for\"\n                },\n                \"base_branch\": {\n                    \"type\": \"string\",\n                    \"description\": \"Base branch to compare against (default: 'main')\",\n                    \"default\": \"main\"\n                },\n                \"filter\": {\n                    \"type\": \"string\",\n                    \"description\": \"Optional filter pattern (simple string match on file path)\"\n                }\n            }\n        }),\n    }\n}\n\n/// Execute the list_changed_files tool\npub fn execute_list_changed_files(args: &Value, _project_root: &Path) -> Result<String> {\n    let change_id = get_required_string(args, \"change_id\")?;\n    validate_change_id(&change_id)?;\n\n    let base_branch =\n        get_optional_string(args, \"base_branch\").unwrap_or_else(|| \"main\".to_string());\n    let filter = get_optional_string(args, \"filter\");\n\n    if !is_git_repo() {\n        anyhow::bail!(\"Not in a git repository\");\n    }\n\n    let mut output = String::new();\n    output.push_str(&format!(\"# Changed Files for: {}\\n\\n\", change_id));\n\n    if let Some(ref f) = filter {\n        output.push_str(&format!(\"**Filter**: `{}`\\n\\n\", f));\n    }\n\n    // Get numstat output\n    let numstat = run_git_command(&[\"diff\", \"--numstat\", &base_branch])?;\n\n    if numstat.is_empty() || numstat.starts_with(\"⚠️\") {\n        output.push_str(\"*No changes detected*\\n\");\n        return Ok(output);\n    }\n\n    // Parse numstat output\n    #[derive(Debug)]\n    struct FileStat {\n        added: String,\n        removed: String,\n        path: String,\n    }\n\n    let mut files: Vec<FileStat> = Vec::new();\n    let mut total_added = 0;\n    let mut total_removed = 0;\n\n    for line in numstat.lines() {\n        let parts: Vec<&str> = line.split('\\t').collect();\n        if parts.len() != 3 {\n            continue;\n        }\n\n        let path = parts[2].to_string();\n\n        // Apply filter if specified\n        if let Some(ref f) = filter {\n            if !path.contains(f) {\n                continue;\n            }\n        }\n\n        let added_str = parts[0].to_string();\n        let removed_str = parts[1].to_string();\n\n        // Parse numbers (handle binary files marked with '-')\n        if added_str != \"-\" {\n            if let Ok(n) = added_str.parse::<usize>() {\n                total_added += n;\n            }\n        }\n        if removed_str != \"-\" {\n            if let Ok(n) = removed_str.parse::<usize>() {\n                total_removed += n;\n            }\n        }\n\n        files.push(FileStat {\n            added: added_str,\n            removed: removed_str,\n            path,\n        });\n    }\n\n    if files.is_empty() {\n        output.push_str(\"*No matching files found*\\n\");\n        return Ok(output);\n    }\n\n    // Format as markdown table\n    output.push_str(\"| File | Status | +Lines | -Lines |\\n\");\n    output.push_str(\"|------|--------|--------|--------|\\n\");\n\n    for file in &files {\n        let status = if file.added == \"-\" && file.removed == \"-\" {\n            \"Binary\"\n        } else if file.removed == \"0\" {\n            \"Added\"\n        } else if file.added == \"0\" {\n            \"Deleted\"\n        } else {\n            \"Modified\"\n        };\n\n        output.push_str(&format!(\n            \"| {} | {} | {} | {} |\\n\",\n            file.path, status, file.added, file.removed\n        ));\n    }\n\n    output.push_str(\"\\n\");\n    output.push_str(&format!(\n        \"**Totals**: {} files, +{} lines, -{} lines\\n\",\n        files.len(),\n        total_added,\n        total_removed\n    ));\n\n    Ok(output)\n}\n````\n\n## Changes\n<!-- type: changes lang: yaml -->\n\n```yaml\nchanges:\n  - path: apps/agentic-workflow/src/tools/implementation.rs\n    action: modify\n    section: source\n    impl_mode: codegen\n    replaces:\n      - \"list_changed_files_definition\"\n      - \"execute_list_changed_files\"\n    description: \"Tool definition and execution for changed-file listing with additions/deletions statistics.\"\n```\n"
